import{_ as n,l as i,o as e,c as l,v as t,p as s,x as r,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"网络分段","description":"","frontmatter":{"title":"网络分段","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/network-segmentation.md","filePath":"cs/network-segmentation.md","lastUpdated":1789023840000}'),c={name:"cs/network-segmentation.md"};function _(E,a,m,u,A,B){const o=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="网络分段" tabindex="-1">网络分段 <a class="header-anchor" href="#网络分段" aria-label="Permalink to &quot;网络分段&quot;">​</a></h1><div class="epigraph"><p>扁平二层让一次失陷走遍。分段把主体与客体放进不同可达性域：管理网、生产、用户、访客。零信任不取消分段，分段降低爆炸半径。</p><footer>—— 据 Saltzer 最小特权；NIST SP 800-207 与分段的关系；对照[VPN 对零信任](/cs/vpn-zero-trust)</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/port-scanning">扫描</a>列出开着的口。缺口是<strong>即使口开着也不该从该区连到</strong>。本课讲 VLAN、防火墙域、微分段，不写打通隔离的步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>ARP 课已说明同 L2 危险。生产数据库不应与访客 Wi-Fi 同域。缺口是策略：默认拒绝跨段，显式允许。</p><h3 id="东西向" tabindex="-1">东西向 <a class="header-anchor" href="#东西向" aria-label="Permalink to &quot;东西向&quot;">​</a></h3><p>数据中心内部流量常被忘。微分段把策略落到工作负载。</p><p><span class="marginnote">Anderson 对扁平网络。禁止逃逸分段教程。默认配置下一课是主机层。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画区：用户、应用、数据、管理。对照零信任：分段是网络实现最小特权的一种。下一课默认配置加固。</p>',12)),(e(),s(h,null,{default:r(()=>[p(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20FLAT%5B%22%E6%89%81%E5%B9%B3%E5%8F%AF%E8%BE%BE%22%5D%20--%3E%20BLAST%5B%22%E7%88%86%E7%82%B8%E5%8D%8A%E5%BE%84%E5%A4%A7%22%5D%0A%20%20SEG%5B%22%E5%88%86%E5%8C%BA%E9%BB%98%E8%AE%A4%E6%8B%92%E7%BB%9D%22%5D%20--%3E%20ALLOW%5B%22%E6%98%BE%E5%BC%8F%E5%85%81%E8%AE%B8%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>可达性是授权的物理近似。仍要应用 BOLA。默认口令下一课常让分段形同虚设。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写跨 VLAN 攻击。扁平二层仍会把 ARP 课的映射问题放大。默认配置加固下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>扫描揭示端口；分段限制谁能连。</li><li>默认拒绝跨段；管理面单独。</li><li>与零信任叠加，不互相取消。</li><li>下一课默认配置。</li><li>出处：Saltzer and Schroeder；NIST SP 800-207；Anderson。</li></ul>',8))])}const P=n(c,[["render",_]]);export{S as __pageData,P as default};
